1	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25 };
2	
3	export const basePremium = (items: { type: string }[]): number => {
4	  return items.reduce((sum, item) => sum + basePremiumsByType[item.type], 0);
5	};
6	
7	export const runScenario = (scenario: unknown): unknown => undefined;
8

1	import { describe, it, expect } from "vitest";
2	import { basePremium, runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — base premiums and component blocks", () => {
5	  // Base premiums for main items (price list)
6	  it("single sword → 100 G base premium", () => {
7	    expect(basePremium([{ type: "sword" }])).toBe(100);
8	  });
9	  it("single amulet → 60 G base premium", () => {
10	    expect(basePremium([{ type: "amulet" }])).toBe(60);
11	  });
12	  it("single staff → 80 G base premium", () => {
13	    expect(basePremium([{ type: "staff" }])).toBe(80);
14	  });
15	  it("single potion → 40 G base premium", () => {
16	    expect(basePremium([{ type: "potion" }])).toBe(40);
17	  });
18	  it("single component (rune) → 25 G base premium", () => {
19	    expect(basePremium([{ type: "rune" }])).toBe(25);
20	  });
21	
22	  // Building block of 3 alike components
23	  it("2 runes → 50 G base premium (no block)", () => {
24	    expect(basePremium([{ type: "rune" }, { type: "rune" }])).toBe(50);
25	  });
26	  it.todo("3 runes → 60 G base premium (block applies)");
27	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
28	  it.todo("7 runes → 175 G base premium");
29	
30	  // "Alike" components — ❓ resolved: alike means exactly the same type
31	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
32	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
33	});
34	
35	describe("MHPCO Claim Office — quote premiums with modifiers", () => {
36	  // Processing fee
37	  it.todo("empty item list → premium 5 G (only the processing fee)");
38	
39	  // Integration example: newcomer with a cursed sword
40	  it.todo("newcomer (0 years, first contract) cursed sword (steel, ench 3) → premium 165 G");
41	
42	  // Integration example: long-standing customer's second contract
43	  it.todo("long-standing (3 years) second contract cursed sword (steel, ench 7) → premium 160 G");
44	
45	  // ❓ first insurance meaning: each item in a quote is treated as first insurance
46	  it.todo("first-insurance surcharge still applies to a new item on a follow-up contract");
47	
48	  // Modifier scope on multi-item policies — ❓ resolved
49	  it.todo("cursed sword + plain amulet (0 years, first contract) → curse surcharge is 50% of the cursed item's base only");
50	
51	  // Modifier thresholds
52	  it.todo("customer with exactly 2 years → loyalty discount applies");
53	  it.todo("customer with 1 year → no loyalty discount");
54	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
55	  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
56	  it.todo("sword with enchantment 4 (not cursed) → no high-enchantment or curse surcharge");
57	
58	  // Rounding in the MHPCO's favor (premium rounds up)
59	  it.todo("premium calculation yielding a half (X.5) → rounded up in MHPCO's favor");
60	});
61	
62	describe("MHPCO Claim Office — claim payouts", () => {
63	  // Standard reimbursement (no special clauses)
64	  it.todo("regular sword (steel, ench 3), damage 500 G → payout 400 G");
65	  it.todo("rune (value 250 G), damage 200 G → payout 100 G (no enchantment/material clause)");
66	
67	  // Enchantment threshold vs. dragon material
68	  it.todo("dragon sword, ench 8, damage 1000 G → payout 400 G (50% then deductible)");
69	  it.todo("dragon sword, ench 9, damage 1000 G → payout 400 G (both clauses; 50% wins, then deductible)");
70	  it.todo("dragon sword, ench 5, damage 800 G → payout 700 G (dragon full, then deductible)");
71	  it.todo("steel sword, ench 9, damage 1000 G → payout 400 G (high-enchantment 50% then deductible)");
72	
73	  // Deductible per damage event
74	  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible per item)");
75	
76	  // Rounding in the MHPCO's favor (payout rounds down)
77	  it.todo("payout calculation yielding a half (X.5) → rounded down in MHPCO's favor");
78	});
79	
80	describe("MHPCO Claim Office — insurance sum and cap", () => {
81	  it.todo("policy covers sword + amulet → insurance sum 1600 G, cap 3200 G");
82	  it.todo("cursed sword → cap 2000 G (based on unmodified insurance value)");
83	  it.todo("policy covers sword + 3 runes (block) → insurance sum 1750 G (block affects premium only)");
84	  it.todo("two successive claims of 1500 G on a sword (cap 2000) → payouts 1400 G then 600 G, cap exhausted");
85	});
86	
87	describe("MHPCO Claim Office — multiple items of the same type", () => {
88	  it.todo("policy covers two swords → insurance sum 2000 G, cap 4000 G");
89	  it.todo("dragon attack damages both swords → each entry is a separate damage with its own deductible");
90	  it.todo("more damages of a type than insured (two sword damages, one sword) → claim rejected (throws)");
91	});
92	
93	describe("MHPCO Claim Office — error handling", () => {
94	  it.todo("quote with an unknown item type (broomstick) → throws");
95	  it.todo("claim referencing an item not in the policy → throws");
96	  it.todo("claim with a negative damage amount (-200) → throws");
97	});
98	
99	describe("MHPCO Claim Office — CLI", () => {
100	  it.todo("reads a JSON scenario from stdin and writes results JSON to stdout");
101	  it.todo("exits non-zero and writes to stderr on an unknown item type; no results on stdout");
102	  it.todo("exits non-zero on a claim referencing an item not in the policy");
103	  it.todo("exits non-zero on a negative damage amount");
104	});
